const assert = require('node:assert/strict')
const fs = require('node:fs')
;(async () => {
  const { medidaInicialContramarco } = await import('../lib/contramarcoConferencia.ts')
  assert.equal(medidaInicialContramarco(null, 2000), '2000')
  assert.equal(medidaInicialContramarco(1500, 2000), '1500')
  assert.equal(medidaInicialContramarco(0, 2000), '2000')
  assert.equal(medidaInicialContramarco(null, null), '')
  assert.equal(medidaInicialContramarco(null, -2), '')
  assert.equal(medidaInicialContramarco(NaN, 2000), '2000')
  assert.equal(Number(medidaInicialContramarco(1500, 2000)) - 20, 1480)
  const cliente = fs.readFileSync('app/producao/medicao-final/cliente/[clienteId]/page.tsx','utf8')
  const flow = fs.readFileSync('components/medicao-final/ContramarcoFlow.tsx','utf8')
  const pdf = fs.readFileSync('lib/contramarcoConferenciaPdf.ts','utf8')
  assert.match(cliente, /orcamentosParaMedir = tipo === 'contramarco'/)
  assert.match(cliente, /if \(tipo !== 'contramarco'\) \{\s*const fluxo = await verificarFluxoVendaOrcamento/)
  assert.match(flow, /fluxoVendaBloqueado = Boolean\(medicao.orcamento_id\) && fluxoVendaAtivo !== true/)
  assert.match(flow, /Relatório de conferência na obra/)
  assert.match(flow, /folgaLargura === '' \|\| folgaAltura === ''/)
  assert.match(pdf, /NÃO É ORDEM DE CORTE/)
  assert.match(pdf, /item\.orcamento_largura_mm/)
  assert.match(pdf, /Pendente/)
  const del=fs.readFileSync('app/api/medicao-final/[id]/route.ts','utf8')
  const conferencia=fs.readFileSync('app/api/medicao-final/[id]/conferencia/route.ts','utf8')
  assert.ok(del.indexOf('Exclusão bloqueada') < del.indexOf(".from('setor_kanban_itens')"))
  assert.match(del,/\.eq\('status', 'ativa'\)/)
  assert.match(conferencia,/if \(medicao\.tipo_medicao === 'contramarco'\) consultaVenda\.eq\('status', 'ativa'\)/)
  console.log('PASS: referência, correção, folgas, acesso separado, bloqueio comercial e relatório de conferência.')
})().catch(e => { console.error(e); process.exitCode=1 })
